{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table maplemonk.saadaa_product_performance_report as with dates as ( select date from unnest(generate_date_array(\'2023-01-01\', current_date())) as date ), all_skus as ( select distinct upper(replace(replace(replace(replace(sku,\'-\',\'_\'),\'_\',\'\'),\' \',\'\'),\'\\'\',\'\')) as sku from maplemonk.saadaa_grn_fact_items union distinct select distinct upper(replace(replace(replace(replace(commonsku,\'-\',\'_\'),\'_\',\'\'),\' \',\'\'),\'\\'\',\'\')) as sku from maplemonk.saadaa_sales_consolidated union distinct select distinct upper(replace(replace(replace(replace(sku,\'-\',\'_\'),\'_\',\'\'),\' \',\'\'),\'\\'\',\'\')) as sku from maplemonk.saadaa_inventory_planning ), calendar_sku_base as ( select d.date, s.sku from dates d cross join all_skus s ), grn as ( select upper(replace(replace(replace(replace(sku,\'-\',\'_\'),\'_\',\'\'),\' \',\'\'),\'\\'\',\'\')) as sku, grn_created_date as date, sum(ifnull(received_quantity,0)) as grn_inward_quantity from maplemonk.saadaa_grn_fact_items group by 1,2 ), sales as ( select upper(replace(replace(replace(replace(commonsku,\'-\',\'_\'),\'_\',\'\'),\' \',\'\'),\'\\'\',\'\')) as sku, date(order_date) as date, sum(ifnull(quantity,0)) as sold_quantity from maplemonk.saadaa_sales_consolidated where lower(gross_order_type) like \'%sale%\' group by 1,2 ), returns as ( select upper(replace(replace(replace(replace(sku,\'-\',\'_\'),\'_\',\'\'),\' \',\'\'),\'\\'\',\'\')) as sku, date(order_date) return_date, ifnull(sum(case when r_flag = 1 and lower(request_type) = \'return\' then return_quantity else 0 end),0) as return_quantity, ifnull(sum(case when r_flag = 1 and lower(request_type) = \'exchange\' then return_quantity else 0 end),0) as exchanged_quantity, sum(ifnull(order_quantity, 0)) as order_quantity from maplemonk.saadaa_returns_consolidated group by 1,2 ), inventory_planning_agg as ( select date_day as date, upper(replace(replace(replace(replace(sku,\'-\',\'_\'),\'_\',\'\'),\' \',\'\'),\'\\'\',\'\')) as sku, max(weighted_doq_45) as weighted_doq_45, max(doq_365) as doq_365, sum(current_stock) as current_stock from maplemonk.saadaa_inventory_planning group by 1,2 ), inventory_ageing as ( select upper(replace(replace(replace(replace(sku, \'-\', \'_\'), \'_\', \'\'), \' \', \'\'), \'\\'\', \'\')) as sku, sum(case when cast(days_in_warehouse as int64) >= 90 then safe_cast(quantity as int64) else 0 end) as inventory_ageing_over_90, sum(case when cast(days_in_warehouse as int64) < 90 then safe_cast(quantity as int64) else 0 end) as inventory_ageing_under_90 from maplemonk.easyecom_full_inventory_report group by 1 ), oos as ( select date(date_day) as date, upper(replace(replace(replace(replace(sku,\'-\',\'_\'),\'_\',\'\'),\' \',\'\'),\'\\'\',\'\')) as sku, max(oos_in_last_45_days) as oos_l45d from maplemonk.saadaa_oos_tracker where lower(warehouse) like \'%main warehouse%\' group by 1, 2 ), rto as ( select date(coalesce(original_return_request_date,return_date)) as date, upper(replace(replace(replace(replace(sku,\'-\',\'_\'),\'_\',\'\'),\' \',\'\'),\'\\'\',\'\')) as sku, sum(total_returned_quantity) as rto_quantity, from saadaa-wh.maplemonk.saadaa_returns_consolidated where return_flag = 1 and return_request_type = \'rto\' group by 1,2 ), inventory_snapshot_union as ( select date(datetime_add(parse_datetime(\'%Y-%m-%d %H:%M:%S\',i.Report_Generated_Date), Interval 3 hour)) date, upper(replace(replace(replace(replace(replace(i.sku,\'-\',\'_\'),\'_\',\'\'),\' \',\'\'),\'`\',\'\'),\'\\'\',\'\')) as sku, cast(available_quantity as int64) as inventory from maplemonk.easyecom_saada_inventory_snapshot i where not(upper(location) like \'%ebo001%\') union all select date(cast(date as datetime)) as date, upper(replace(replace(replace(replace(replace(commonsku,\'-\',\'_\'),\'_\',\'\'),\' \',\'\'),\'`\',\'\'),\'\\'\',\'\')) as sku, cast(ending_warehouse_balance as int64) as inventory from maplemonk.amazon_fba_location_wise_inventory_fact_items union all select date_add(date(parse_date(\'%d-%m-%Y\', date)),interval 1 day) as date, upper(replace(replace(replace(replace(replace(sub_category,\'-\',\'_\'),\'_\',\'\'),\' \',\'\'),\'`\',\'\'),\'\\'\',\'\')) as sku, cast(replace(closing_quantity,\'.00\',\'\') as int64) as inventory from maplemonk.s3_saadaa_store_daily_inventory ), daily_closing_inventory as ( select date, sku, sum(ifnull(inventory, 0)) as closing_inventory from inventory_snapshot_union group by 1, 2 ) select base.sku as sku, base.date as date, p.product_name, p.category, p.sub_category, p.color_family, p.size, p.cost, inventory_ageing_over_90, inventory_ageing_under_90, grn.grn_inward_quantity, s.sold_quantity as daily_sold_quantity, oos.oos_l45d, ip.current_stock, greatest(coalesce(ip.weighted_doq_45, 0.25), coalesce(ip.doq_365, 0.25)) as doq, safe_divide(ifnull(ip.current_stock, 0), greatest(coalesce(ip.weighted_doq_45, 0.25), coalesce(ip.doq_365, 0.25))) as doh, r.order_quantity, r.exchanged_quantity, r.return_quantity, rto.rto_quantity, ifnull(dci.closing_inventory, 0) as closing_inventory, lag(ifnull(dci.closing_inventory, 0)) over (partition by base.sku order by base.date) as opening_inventory, from calendar_sku_base base left join (select * from (select replace(marketplace_sku,\' \',\'\') skucode, lower(replace(replace(replace(commonsku,\'-\',\'_\'),\'_\',\'\'),\' \',\'\')) commonsku, product_name, cast(category as string) category, cast(sub_category as string) as sub_category, categorytype, dyed_fabric_sku, rm_fabric_sku, case when fabric_consumption_average <> \'#n/a\' then cast(fabric_consumption_average as float64) else 0 end fabric_consumption_average, color_family, product_type, product_variant, size, cost, row_number() over (partition by replace(replace(replace(commonsku,\'-\',\'_\'),\'_\',\'\'),\' \',\'\') order by 1) rw from saadaa-wh.maplemonk.saadaa_final_sku_master ) where rw = 1 ) p on lower(replace(base.sku,\' \',\'\')) = lower(p.commonsku) left join inventory_ageing ia on base.sku = ia.sku left join grn on base.sku = grn.sku and base.date = grn.date left join sales s on base.sku = s.sku and base.date = s.date left join oos on base.sku = oos.sku and base.date = oos.date left join returns r on base.sku = r.sku and base.date = r.return_date left join rto on base.sku = rto.sku and base.date = rto.date left join inventory_planning_agg ip on base.sku = ip.sku and base.date = ip.date left join daily_closing_inventory dci on base.sku = dci.sku and base.date = dci.date;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

